var runningCount = 0;
// PATCH 1.0.13: в свёрнутом виде tasks = [{task_id:'__collapsed__', task_status:'active'}],
// поэтому считаем по allTasks, иначе счётчик всегда 1.
allTasks.forEach(function(tt) {
    var st = (tt.task_status || 'active');
    if (st === 'active' || st === 'paused') runningCount++;
});

// PATCH 1.0.13: один тег = полный круг. Path с a1===a2 (mod 2π) невидим,
// поэтому рисуем <circle> с обводкой, толщина = (r - inner).
if (slice >= Math.PI * 2 - 0.01) {
    var midR = (r + inner) / 2;
    var strokeW = r - inner;
    svg += '<circle class="chart-slice" data-tag="' + escapeHtml(t.tag) + '" '
        + 'cx="' + cx + '" cy="' + cy + '" r="' + midR + '" '
        + 'fill="none" stroke="' + color + '" stroke-width="' + strokeW + '">'
        + '<title>#' + escapeHtml(t.tag) + ': ' + v + ' ч · клик → фильтр по тегу</title></circle>';
} else {
    svg += '<path class="chart-slice" data-tag="' + escapeHtml(t.tag) + '" '
        + 'd="M ' + x1.toFixed(2) + ' ' + y1.toFixed(2)
        + ' A ' + r + ' ' + r + ' 0 ' + large + ' 1 ' + x2.toFixed(2) + ' ' + y2.toFixed(2)
        + ' L ' + xi2.toFixed(2) + ' ' + yi2.toFixed(2)
        + ' A ' + inner + ' ' + inner + ' 0 ' + large + ' 0 ' + xi1.toFixed(2) + ' ' + yi1.toFixed(2)
        + ' Z" fill="' + color + '">'
        + '<title>#' + escapeHtml(t.tag) + ': ' + v + ' ч · клик → фильтр по тегу</title></path>';
}

