/* PATCH 1.0.13: индексация с ограничением видимым окном */
function _idxForDate(dk) {
    if (!dk) return 0;
    if (dk < days[0]) return 0;
    if (dk > days[days.length - 1]) return days.length - 1;
    for (var i = 0; i < days.length; i++) if (days[i] === dk) return i;
    return 0;
}

/* Строки задач */
tasks.forEach(function(t) {
    var cls = t.overdue ? 'overdue' : (t.status || 'active');
    var sIdx = _idxForDate(t.start_date);
    var eIdx = _idxForDate(t.deadline);
    if (eIdx < sIdx) eIdx = sIdx;

    // План — контур (2px dashed)
    var planLeft = sIdx * DAY_W + 3;
    var planWidth = (eIdx - sIdx + 1) * DAY_W - 6;
    if (planWidth < 16) planWidth = 16;

    // Факт — цветная заливка
    var factStartIdx = sIdx;
    var factEndIdx = eIdx;
    var factCls = cls;
    var factTitle = '';
    var completedIso = (t.completed_at || '').slice(0, 10);
    if (completedIso) {
        var cIdx = _idxForDate(completedIso);
        if (cIdx < factStartIdx) cIdx = factStartIdx;
        factEndIdx = cIdx;
        var deadlineIso = (t.deadline || '').slice(0, 10);
        if (deadlineIso && completedIso <= deadlineIso) {
            factCls = 'done-early';
            factTitle = ' · закрыто досрочно (' + completedIso + ')';
        } else if (deadlineIso && completedIso > deadlineIso) {
            factCls = 'done-late';
            factTitle = ' · закрыто с опозданием (' + completedIso + ')';
        } else {
            factCls = 'done';
            factTitle = ' · закрыто (' + completedIso + ')';
        }
    } else {
        // не закрыта — факт до today (если today внутри плана)
        var todayIdx = today ? _idxForDate(today) : -1;
        if (todayIdx >= 0 && todayIdx > sIdx && todayIdx < eIdx) {
            factEndIdx = todayIdx;
        }
    }

    var factLeft = factStartIdx * DAY_W + 3;
    var factWidth = (factEndIdx - factStartIdx + 1) * DAY_W - 6;
    if (factWidth < 16) factWidth = 16;

    var title = t.name + ' · план: ' + t.start_date + ' — ' + t.deadline +
                (t.overdue ? ' · ПРОСРОЧЕНО' : '') + factTitle;

    html += '<div class="gg-row">';
    html +=   '<div class="gg-name">';
    html +=     '<span class="gg-dot gg-dot-' + cls + '"></span>';
    html +=     '<span class="gg-ico">' + esc(t.icon || '📋') + '</span>';
    html +=     '<span class="gg-task-name" title="' + esc(t.name) + '">' + esc(t.name) + '</span>';
    html +=   '</div>';
    html +=   '<div class="gg-track" style="width:' + trackW + 'px">';
    // 1. Контур плана (сзади, pointer-events: none)
    html +=     '<div class="gg-bar-plan" style="left:' + planLeft + 'px;width:' + planWidth + 'px" title="План: ' + esc(t.start_date) + ' — ' + esc(t.deadline) + '"></div>';
    // 2. Факт (заливка)
    html +=     '<div class="gg-bar gg-bar-' + factCls + '" style="left:' + factLeft + 'px;width:' + factWidth + 'px" title="' + esc(title) + '">';
    if (factWidth > 80) {
        html +=     '<span class="gg-bar-label">' + esc(t.name) + '</span>';
    }
    html +=     '</div>';
    html +=   '</div>';
    html += '</div>';
});

.gg-bar-planned { background: linear-gradient(180deg, #b0bec5, #607d8b); }
/* PATCH 1.0.13: план — контур; факт — заливка по завершению */
.gg-bar-plan {
    position: absolute;
    top: 50%;
    transform: translateY(-50%);
    height: 24px;
    border-radius: 8px;
    background: transparent;
    border: 2px dashed rgba(128, 128, 128, 0.40);
    pointer-events: none;
    z-index: 1;
    box-sizing: border-box;
}
.gg-bar-done-early {
    background: linear-gradient(180deg, #7be0a0, #239b56) !important;
}
.gg-bar-done-late {
    background: linear-gradient(180deg, #f08b80, #b03a2e) !important;
}
body.trk-theme-light .gg-bar-plan {
    border-color: rgba(0, 0, 0, 0.28);
}
